callGraph.callee:
(() => {
    const raw = data && data.valuation_updated_at
    if (!raw) return ''
    const iso = /Z|[+-]\d\d:?\d\d$/.test(raw) ? raw : String(raw).replace(' ', 'T') + 'Z'
    const at = new Date(iso)
    return Number.isNaN(at.getTime()) ? '' : at.toLocaleString(window.WyckoffI18n.getLang())
  })
